#!/usr/bin/env node
/**
 * Regenerates `src/validate/spec-tables.gen.ts` from the published R4 core package.
 *
 * The two tables it writes — the set of R4 resource type names, and the top-level
 * elements each one declares with min >= 1 — are facts about the specification, not
 * opinions. Deriving them from `hl7.fhir.r4.core#4.0.1` rather than typing them out
 * means they cannot quietly disagree with the validator that CI runs, which is the
 * failure mode a hand-maintained list always eventually has.
 *
 * The generated file is checked in, so neither the build nor CI needs the FHIR
 * package cache. Run this only when moving to a different R4 release.
 *
 *   node tools/generate-spec-tables.mjs [pathToHl7FhirR4CorePackage]
 */

import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

// biome-ignore lint/suspicious/noConsole: a command-line tool whose output is the product
const say = (message) => console.log(message);
// biome-ignore lint/suspicious/noConsole: a command-line tool whose output is the product
const fail = (message) => console.error(message);

const HERE = dirname(fileURLToPath(import.meta.url));
const DEFAULT_PACKAGE = join(homedir(), '.fhir', 'packages', 'hl7.fhir.r4.core#4.0.1', 'package');
const source = process.argv[2] ?? DEFAULT_PACKAGE;

let files;
try {
  files = readdirSync(source).filter((name) => name.startsWith('StructureDefinition-') && name.endsWith('.json'));
} catch {
  fail(`FAIL: no R4 core package at ${source}.`);
  fail('Fetch it with the HL7 validator or `npm i -g fhir` and pass the package directory.');
  process.exit(1);
}

const resourceTypes = [];
const required = {};

for (const file of files) {
  const definition = JSON.parse(readFileSync(join(source, file), 'utf8'));
  if (definition.kind !== 'resource' || definition.abstract === true || definition.derivation === 'constraint') {
    continue;
  }
  const type = definition.type;
  resourceTypes.push(type);

  const elements = definition.snapshot?.element ?? [];
  const mandatory = elements
    .filter((element) => {
      const path = element.path ?? '';
      // Top-level only. Nested cardinality is profile-shaped work and is the HL7
      // validator's job, not this package's.
      return path.startsWith(`${type}.`) && !path.slice(type.length + 1).includes('.') && (element.min ?? 0) >= 1;
    })
    .map((element) => element.path.slice(type.length + 1));

  if (mandatory.length > 0) required[type] = mandatory;
}

resourceTypes.sort();

if (resourceTypes.length < 100) {
  fail(`FAIL: only ${resourceTypes.length} resource types found. Refusing to write a truncated table.`);
  process.exit(1);
}

const lines = [
  '/**',
  ' * GENERATED by tools/generate-spec-tables.mjs from hl7.fhir.r4.core#4.0.1. Do not edit.',
  ' *',
  ' * `R4_RESOURCE_TYPES` is every concrete resource type FHIR R4 defines.',
  ' * `R4_REQUIRED_ELEMENTS` is, per resource type, the top-level elements the base',
  ' * specification declares with min >= 1. Names ending in `[x]` are choice types and',
  ' * are satisfied by any one of their typed forms.',
  ' */',
  '',
  'export const R4_RESOURCE_TYPES: ReadonlySet<string> = new Set([',
  ...resourceTypes.map((type) => `  '${type}',`),
  ']);',
  '',
  'export const R4_REQUIRED_ELEMENTS: Readonly<Record<string, readonly string[]>> = {',
  ...Object.keys(required)
    .sort()
    .map((type) => `  ${JSON.stringify(type)}: [${required[type].map((e) => `'${e}'`).join(', ')}],`),
  '};',
  ''
];

const out = join(HERE, '..', 'src', 'validate', 'spec-tables.gen.ts');
writeFileSync(out, lines.join('\n'));
say(`Wrote ${resourceTypes.length} resource types and ${Object.keys(required).length} required-element rows`);
say(`  -> ${out}`);
